(function(){function q(e,s){return e.querySelector(s)}function qs(e,s){return Array.prototype.slice.call(e.querySelectorAll(s))}function params(el){var f=el.tagName==="FORM"?el:el.closest("form");return f?new URLSearchParams(new FormData(f)).toString():""}function req(el){var u=el.getAttribute("hx-get");if(!u)return;var p=params(el),t=el.getAttribute("hx-target"),target=t?q(document,t):el,s=el.getAttribute("hx-swap")||"innerHTML";if(p)u+=(u.indexOf("?")>=0?"&":"?")+p;fetch(u,{headers:{"HX-Request":"true"}}).then(function(r){return r.text()}).then(function(h){if(!target)return;if(s==="outerHTML")target.outerHTML=h;else target.innerHTML=h})}function bind(root){qs(root,"[hx-get]").forEach(function(el){var tr=(el.getAttribute("hx-trigger")||"click").split(",").map(function(x){return x.trim().split(" ")[0]});tr.forEach(function(ev){if(ev==="load"){req(el);return}el.addEventListener(ev,function(e){if(ev==="submit")e.preventDefault();req(el)})})})}document.addEventListener("DOMContentLoaded",function(){bind(document)})})();
